-- 0094: MYP2 Formative Assessment 2 (Criteria A-D) - every question stem now carries
-- an instruction sentence with a command term (parts already had command terms).
-- Rewording only: parts, answers, hints, marks, strands unchanged.
begin;
update questions set prompt = 'The tape diagram shows flour and sugar for a pastry recipe in the ratio 4 : 1. The total mass is 500 g. Find the mass of one equal part, then calculate the mass of flour, in parts (a) and (b).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The tape diagram shows flour and sugar for a pastry recipe in the ratio 4 : 1. The total mass is 500 g. Find the mass of one equal part, then calculate the mass of flour, in parts (a) and (b)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"tape","title":"Flour : sugar (500 g in total)","tapeRows":[{"label":"Flour","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]},{"label":"Sugar","segments":[{"label":"?","span":1}]}]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 3;
update questions set prompt = 'The Venn diagram shows students in a class who study Art (A) and Music (M). Write down the value of n(A), then calculate how many students study exactly one of the two subjects, in parts (a) and (b).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Venn diagram shows students in a class who study Art (A) and Music (M). Write down the value of n(A), then calculate how many students study exactly one of the two subjects, in parts (a) and (b)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Art and Music students","venn":{"leftLabel":"A","rightLabel":"M","leftOnly":"11","both":"6","rightOnly":"8","outside":"5","universalLabel":"ξ = class"}}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 5;
update questions set prompt = 'For the universal set ξ = {multiples of 3 up to 30}, set T is the multiples of 4 within ξ. Write down the value of n(T) and the value of n(T′), the complement of T, in parts (a) and (b).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the universal set ξ = {multiples of 3 up to 30}, set T is the multiples of 4 within ξ. Write down the value of n(T) and the value of n(T′), the complement of T, in parts (a) and (b)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Universal set ξ","columns":["ξ = multiples of 3 up to 30"],"rows":[["3, 6, 9, 12, 15, 18, 21, 24, 27, 30"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 6;
update questions set prompt = 'The double number line shows that 5 notebooks cost €20 at a stationery shop. Calculate the cost of one notebook, then calculate how many notebooks can be bought for €36, in parts (a) and (b).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The double number line shows that 5 notebooks cost €20 at a stationery shop. Calculate the cost of one notebook, then calculate how many notebooks can be bought for €36, in parts (a) and (b)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"double_number_line","title":"Cost of notebooks","lines":[{"label":"Notebooks","unit":"books","max":9,"ticks":[{"at":0,"label":"0"},{"at":5,"label":"5"},{"at":9,"label":"?"}]},{"label":"Cost","unit":"€","max":36,"ticks":[{"at":0,"label":"0"},{"at":20,"label":"20"},{"at":36,"label":"36"}]}]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 8;
update questions set prompt = 'A baker investigates how the cost of croissants depends on the number bought. The bakery charges a single price per croissant with no bulk discount. Find the cost of 6 and of 9 croissants, describe the general rule as a formula, then verify your rule, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A baker investigates how the cost of croissants depends on the number bought. The bakery charges a single price per croissant with no bulk discount. Find the cost of 6 and of 9 croissants, describe the general rule as a formula, then verify your rule, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Croissant prices","columns":["Croissants","2","4","6","9"],"rows":[["Cost ($)","4.50","9.00","?","?"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 10;
update questions set prompt = 'A leaking pipe is investigated. The volume of water collected is measured every 2 minutes and the leak is steady. Find the volume collected after 10 and after 15 minutes, write a general rule, then verify your rule, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A leaking pipe is investigated. The volume of water collected is measured every 2 minutes and the leak is steady. Find the volume collected after 10 and after 15 minutes, write a general rule, then verify your rule, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Leak investigation","columns":["Time t (min)","2","4","6","10","15"],"rows":[["Volume V (L)","0.8","1.6","2.4","?","?"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 11;
update questions set prompt = 'A tile designer repeats a motif. The table shows the number of dark tiles and light tiles in each design size. Find the numbers of dark and light tiles in size 5, write a general rule, then verify your rule, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A tile designer repeats a motif. The table shows the number of dark tiles and light tiles in each design size. Find the numbers of dark and light tiles in size 5, write a general rule, then verify your rule, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Tile motif investigation","columns":["Size n","1","2","3","4","5"],"rows":[["Dark tiles","3","5","7","9","?"],["Light tiles","5","8","11","14","?"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 12;
update questions set prompt = 'A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials. Write down the relative frequency after 200 drops, estimate the point-up landings in 1000 drops, describe the pattern, then verify with 400 drops, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A class investigates a biased drawing pin. It is dropped 200 times and lands point-up 130 times. The experiment is repeated in larger trials. Write down the relative frequency after 200 drops, estimate the point-up landings in 1000 drops, describe the pattern, then verify with 400 drops, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Drawing pin experiment","columns":["Drops","50","100","200","400"],"rows":[["Point-up","34","63","130","…"],["Relative frequency","0.68","0.63","0.65","…"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 13;
update questions set prompt = 'A teacher investigates club membership. In a year group, 26 students play in the orchestra (O), 19 are in the choir (C), and 8 do both. The year group has 50 students. Find the number of students in the orchestra only, calculate how many are in neither club, state the general rule, then verify it, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A teacher investigates club membership. In a year group, 26 students play in the orchestra (O), 19 are in the choir (C), and 8 do both. The year group has 50 students. Find the number of students in the orchestra only, calculate how many are in neither club, state the general rule, then verify it, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Orchestra and Choir","venn":{"leftLabel":"O","rightLabel":"C","leftOnly":"?","both":"8","rightOnly":"?","outside":"?","universalLabel":"ξ = 50 students"}}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 14;
update questions set prompt = 'A print shop investigates paper costs. The table shows the cost of printing booklets when the same price per booklet applies. Find the cost of printing 20 and 35 booklets, write the general rule, then verify your rule, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A print shop investigates paper costs. The table shows the cost of printing booklets when the same price per booklet applies. Find the cost of printing 20 and 35 booklets, write the general rule, then verify your rule, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Booklet printing costs","columns":["Booklets n","4","12","20","35"],"rows":[["Cost C ($)","10","30","?","?"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 15;
update questions set prompt = 'The Venn diagram shows students who take the bus (B) and cycle (C). Write down the value of each expression in parts (a) and (b), using correct set notation.', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Venn diagram shows students who take the bus (B) and cycle (C). Write down the value of each expression in parts (a) and (b), using correct set notation."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Getting to school","venn":{"leftLabel":"B","rightLabel":"C","leftOnly":"9","both":"4","rightOnly":"7","outside":"6","universalLabel":"ξ = students"}}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 17;
update questions set prompt = 'The graph shows the cost of hiring a kayak, where cost is proportional to time. Find the cost of 3 hours using the graph, then calculate how many hours can be hired for $25, in parts (a) and (b).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The graph shows the cost of hiring a kayak, where cost is proportional to time. Find the cost of 3 hours using the graph, then calculate how many hours can be hired for "},{"type":"text","text":"$25, in parts (a) and (b)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"term_graph","title":"Kayak hire cost","xLabel":"Time (hours)","yLabel":"Cost ($)","xMin":0,"xMax":6,"yMin":0,"yMax":30,"points":[[0,0],[1,5],[2,10],[3,15],[4,20],[5,25],[6,30]],"joinPoints":true}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 18;
update questions set prompt = 'A decorator mixes green paint from blue and yellow in the ratio 3 : 7. She needs 20 litres of green paint for a community hall. Identify the total number of equal parts, calculate the litres of blue and yellow paint needed, then state whether buying 6 one-litre tins of blue paint is enough, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A decorator mixes green paint from blue and yellow in the ratio 3 : 7. She needs 20 litres of green paint for a community hall. Identify the total number of equal parts, calculate the litres of blue and yellow paint needed, then state whether buying 6 one-litre tins of blue paint is enough, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"tape","title":"Blue : yellow (ratio 3 : 7)","tapeRows":[{"label":"Blue","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]},{"label":"Yellow","segments":[{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1},{"label":"?","span":1}]}]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 21;
update questions set prompt = 'On a school trip, a coach travels 264 km in 4 hours on the motorway, then a further 45 km in 1.5 hours on country roads. Calculate the coach''s speed on the motorway and on the country roads, then calculate the average speed for the whole journey, and state whether 56 km/h is a sensible value to quote, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On a school trip, a coach travels 264 km in 4 hours on the motorway, then a further 45 km in 1.5 hours on country roads. Calculate the coach''s speed on the motorway and on the country roads, then calculate the average speed for the whole journey, and state whether 56 km/h is a sensible value to quote, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Coach journey","columns":["Leg","Distance (km)","Time (h)"],"rows":[["Motorway","264","4"],["Country roads","45","1.5"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 22;
update questions set prompt = 'A school surveys 40 students about the canteen: 23 buy fruit (F), 17 buy yoghurt (Y), and 9 buy both. The canteen manager uses the results to plan stock. Find how many students buy fruit only and how many buy neither item, calculate how many buy at least one item, then state whether the manager should stock fruit for all 40 students, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A school surveys 40 students about the canteen: 23 buy fruit (F), 17 buy yoghurt (Y), and 9 buy both. The canteen manager uses the results to plan stock. Find how many students buy fruit only and how many buy neither item, calculate how many buy at least one item, then state whether the manager should stock fruit for all 40 students, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"venn2","title":"Canteen survey","venn":{"leftLabel":"F","rightLabel":"Y","leftOnly":"?","both":"9","rightOnly":"?","outside":"?","universalLabel":"ξ = 40 students"}}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 23;
update questions set prompt = 'A fairground game uses a spinner with 10 equal sectors: 3 are gold (win), the rest are blank. A stallholder tests the game fairly before opening. Write down P(win), estimate the number of wins in 50 spins, calculate the expected payout, then explain why the actual payout might differ, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A fairground game uses a spinner with 10 equal sectors: 3 are gold (win), the rest are blank. A stallholder tests the game fairly before opening. Write down P(win), estimate the number of wins in 50 spins, calculate the expected payout, then explain why the actual payout might differ, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Fairground spinner","columns":["Sector type","Gold (win)","Blank"],"rows":[["Sectors","3","7"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 24;
update questions set prompt = 'A family drives 420 km to visit relatives. Their car uses fuel at a rate of 7.5 litres per 100 km, and fuel costs $1.60 per litre. Calculate the number of 100 km units in the journey, the litres of fuel needed and the cost of the fuel, then state why the real cost might not be exactly $50.40, in parts (a) to (d).', prompt_doc = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A family drives 420 km to visit relatives. Their car uses fuel at a rate of 7.5 litres per 100 km, and fuel costs "},{"type":"text","text":"$1.60 per litre. Calculate the number of 100 km units in the journey, the litres of fuel needed and the cost of the fuel, then state why the real cost might not be exactly $"},{"type":"text","text":"50.40, in parts (a) to (d)."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"table","title":"Family road trip","columns":["Journey","420 km"],"rows":[["Fuel rate","7.5 L per 100 km"],["Fuel price","$1.60 per litre"]]}}}]}'::jsonb where organization_id = '0a400000-0000-4000-8000-000000000001' and config->>'source' = 'assess2-myp2b-criteria' and (config->>'question_number')::int = 25;
